<student_code untrusted="true">
=== submission_05.ino ===
   1| /*
   2|   Lab 4 - Debounced Toggle
   3| 
   4|   Reads the button on D2 (internal pull-up, so pressed = LOW) and
   5|   toggles the built-in LED once per press. Each new state is sent on
   6|   Serial1 at 9600 baud.
   7| 
   8|   I timestamp with micros() instead of millis() because millis() only
   9|   has 1 ms resolution, so a debounce window of a few ms would have up
  10|   to 1 ms of jitter.
  11| */
  12| 
  13| const uint8_t  kButton = 2;
  14| const uint8_t  kLed = LED_BUILTIN;
  15| const uint32_t kDebounce = 5;      // debounce window
  16| 
  17| bool     ledOn = false;
  18| uint8_t  rawPrev = HIGH;
  19| uint8_t  stable = HIGH;
  20| uint32_t tChange = 0;
  21| 
  22| void setup() {
  23|   pinMode(kButton, INPUT_PULLUP);
  24|   pinMode(kLed, OUTPUT);
  25|   digitalWrite(kLed, LOW);
  26|   Serial1.begin(9600);
  27| }
  28| 
  29| void loop() {
  30|   uint8_t raw = digitalRead(kButton);
  31|   uint32_t now = micros();
  32| 
  33|   // restart the window whenever the raw input moves
  34|   if (raw != rawPrev) {
  35|     rawPrev = raw;
  36|     tChange = now;
  37|   }
  38| 
  39|   // input has settled
  40|   if (now - tChange >= kDebounce && raw != stable) {
  41|     stable = raw;
  42|     if (stable == LOW) {
  43|       ledOn = !ledOn;
  44|       digitalWrite(kLed, ledOn);
  45|       Serial1.println(ledOn ? "ON" : "OFF");
  46|     }
  47|   }
  48| }
</student_code>
